(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,31454,e=>{"use strict";e.s(["citations",0,{"c1-1":{id:"c1-1",marker:1,citation:"Logevall, Fredrik. Embers of War: The Fall of an Empire and the Making of America’s Vietnam. Random House, 2012.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Fredrik Logevall",title:"Embers of War: The Fall of an Empire and the Making of America’s Vietnam",date:"2012",publicationOrArchive:"Random House (Pulitzer Prize in History)",supportsClaim:"Explains how the United States ended up paying for France’s war in Indochina, while ignoring Vietnamese who wanted independence.",limitations:"Mostly about leaders in Washington and Paris, not ordinary people in Vietnam.",originalUrl:"https://openlibrary.org/works/OL20798709W",verificationCategory:"VERIFIED_PARAPHRASE"},"c1-2":{id:"c1-2",marker:2,citation:"Fall, Bernard B. Hell in a Very Small Place: The Siege of Dien Bien Phu. Lippincott, 1966.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Bernard B. Fall",title:"Hell in a Very Small Place: The Siege of Dien Bien Phu",date:"1966",publicationOrArchive:"Lippincott / Da Capo Press",supportsClaim:"The classic account of the battle of Dien Bien Phu, and how Viet Minh artillery broke the French defense.",limitations:"Written in 1966 from French records. Vietnamese records opened since then add more about how the Viet Minh moved their supplies.",originalUrl:"https://openlibrary.org/works/OL77483W",verificationCategory:"VERIFIED_PARAPHRASE"},"c1-3":{id:"c1-3",marker:3,citation:"Herring, George C. America’s Longest War: The United States and Vietnam, 1950–1975. McGraw-Hill, 2013.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"George C. Herring",title:"America’s Longest War: The United States and Vietnam, 1950–1975",date:"2013",publicationOrArchive:"McGraw-Hill (5th Edition)",supportsClaim:"A standard history of how the United States got more and more committed to fighting communism in Southeast Asia.",limitations:"A broad overview. It says more about decisions in Washington than about the fighting itself.",originalUrl:"https://openlibrary.org/works/OL2916071W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q001",chapter:1,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"I therefore earnestly appeal to you personally and to the American people to interfere urgently in support of our independence and help making the negotiations more in keeping with the principles of the Atlantic and San Francisco charters.",exactQuotation:"I therefore earnestly appeal to you personally and to the American people to interfere urgently in support of our independence and help making the negotiations more in keeping with the principles of the Atlantic and San Francisco charters.",source:"Telegram from Ho Chi Minh to President Harry S. Truman (February 28, 1946)",authorOrCreator:"Ho Chi Minh",institution:"Provisional Government of the Democratic Republic of Vietnam",date:"February 28, 1946",sourceUrl:"https://docsteach.org/document/ho-chi-minh-to-truman/",locator:"NARA RG 226, Entry 140, Box 39 / DocsTeach Document ID 595462",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Shows Ho Chi Minh writing to President Truman to ask for U.S. help against France. He pointed to the Atlantic Charter and the United Nations Charter.",limitations:"Truman never answered. Rebuilding ties with France in Europe mattered more to his government.",conversionStatus:"verified_verbatim",notes:'Prior site text conflated phrases from Ho Chi Minh’s October 17, 1945 letter ("fight to the last drop of blood") with this February 28, 1946 telegram. The two documents have been separated into Q001 and Q001B. Verbatim telegram wording verified against NARA RG 226 / DocsTeach ID 595462.'},{id:"Q001B",chapter:1,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"Our Vietnam people, after so many years of oppression and devastation under the French and the Japanese, are determined to fight to the last drop of blood rather than submit again to foreign slavery.",exactQuotation:"Our Vietnam people, after so many years of oppression and devastation under the French and the Japanese, are determined to fight to the last drop of blood rather than submit again to foreign slavery.",source:"Letter from Ho Chi Minh to President Harry S. Truman (October 17, 1945)",authorOrCreator:"Ho Chi Minh",institution:"Provisional Government of the Democratic Republic of Vietnam",date:"October 17, 1945",sourceUrl:"https://www.trumanlibrary.gov/library/online-collections",locator:"NARA RG 226, Entry 140 / Truman Library Papers of Harry S. Truman",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Shows Ho Chi Minh telling President Truman, right after Japan surrendered, that Vietnam was an independent country.",limitations:"It reached Washington through an American intelligence office in China. Truman chose not to answer, to avoid upsetting France.",conversionStatus:"verified_verbatim",notes:"Separated from Q001 to resolve prior conflation. Text confirmed in NARA OSS records and diplomatic correspondence collections."},{id:"Q002",chapter:1,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"It is important to United States security interests that all practicable measures be taken to prevent further communist expansion in Southeast Asia. Indochina is a key area of Southeast Asia and is under immediate threat.",exactQuotation:"It is important to United States security interests that all practicable measures be taken to prevent further communist expansion in Southeast Asia. Indochina is a key area of Southeast Asia and is under immediate threat.",source:"The Position of the United States with Respect to Indochina (NSC 64)",authorOrCreator:"National Security Council",institution:"Executive Office of the President of the United States",date:"February 27, 1950 (Adopted April 24, 1950)",sourceUrl:"https://history.state.gov/historicaldocuments/frus1950v06/d480",locator:"FRUS 1950, Vol. VI, East Asia and the Pacific, Document 480, pp. 745–747, Conclusions Para 10",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The 1950 policy paper, NSC 64, that explained why the United States would help pay for France’s war in Indochina: to stop communism from spreading in the region.",limitations:"It covers Southeast Asia only. Don’t mix it up with NSC 68, the broader Cold War plan written two months later.",conversionStatus:"verified_verbatim",notes:"Verified letter-for-letter against Foreign Relations of the United States (FRUS) 1950, Vol. VI, Document 480. Permanent separation from NSC 68 established."},{id:"Q002B",chapter:1,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"The assault on free institutions is worldwide now, and in the context of the present polarization of power a defeat of free institutions anywhere is a defeat everywhere.",exactQuotation:"The assault on free institutions is worldwide now, and in the context of the present polarization of power a defeat of free institutions anywhere is a defeat everywhere.",source:"United States Objectives and Programs for National Security (NSC 68)",authorOrCreator:"Policy Planning Staff (Paul H. Nitze, Chairman)",institution:"National Security Council",date:"April 14, 1950",sourceUrl:"https://history.state.gov/historicaldocuments/frus1950v01/d85",locator:"FRUS 1950, Vol. I, National Security Affairs, Document 85, pp. 235–292, Section IV",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"NSC 68, the 1950 paper that set out America’s Cold War plan to contain communism everywhere in the world.",limitations:"It is about the whole world, not Vietnam. Don’t treat it as the same document as NSC 64.",conversionStatus:"verified_verbatim",notes:"Separated from NSC 64. Verified against official State Department FRUS publication."},{id:"Q012",chapter:1,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"In his definitive 1966 study Hell in a Very Small Place, Bernard Fall documented how General Henri Navarre’s valley basin fortress at Dien Bien Phu was systematically overwhelmed by Viet Minh artillery assembled on the surrounding heights, rendering the French stronghold an untenable siege position.",source:"Hell in a Very Small Place: The Siege of Dien Bien Phu",authorOrCreator:"Bernard B. Fall",institution:"Howard University / Historical Monograph",date:"1966",sourceUrl:"https://www.worldcat.org/title/hell-in-a-very-small-place/oclc/422204",locator:"Lippincott, 1966, Chapters 4 & 9 (Historical Monograph)",locatorStatus:"supported",verified:!0,sourceType:"SCHOLARLY_SECONDARY_SOURCE",supportsClaim:"Explains how France lost at Dien Bien Phu. The French did not believe the Viet Minh could get big guns onto the hills above the valley, and they were wrong.",limitations:"Fall wrote in 1966. A line often credited to him about the fortress being an open grave is not in his book, so we don’t quote it.",conversionStatus:"converted_to_paraphrase",notes:"Verified that the underlying historical analysis matches Fall’s book, but exact quotation was synthetic. Rendered as an attributed analytical paraphrase."}]],23360);var t=e.i(23360);e.s(["citations",0,{"c2-1":{id:"c2-1",marker:1,citation:"Asselin, Pierre. Hanoi’s Road to the Vietnam War, 1954–1965. University of California Press, 2013.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Pierre Asselin",title:"Hanoi’s Road to the Vietnam War, 1954–1965",date:"2013",publicationOrArchive:"University of California Press",supportsClaim:"Uses Vietnamese Communist Party records to show how Hanoi’s leaders argued their way to Resolution 15 and the decision to fight in the South.",limitations:"Focused on the leaders in Hanoi, not the fighters in the South.",originalUrl:"https://openlibrary.org/works/OL21542893W",verificationCategory:"VERIFIED_PARAPHRASE"},"c2-2":{id:"c2-2",marker:2,citation:"Jacobs, Seth. America’s Miracle Man in Vietnam: Ngo Dinh Diem, Religion, Race, and U.S. Intervention in Southeast Asia. Duke University Press, 2004.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Seth Jacobs",title:"America’s Miracle Man in Vietnam: Ngo Dinh Diem, Religion, Race, and U.S. Intervention",date:"2004",publicationOrArchive:"Duke University Press",supportsClaim:"Shows how the Eisenhower administration built up Ngo Dinh Diem as an anti-communist hero and looked past the harsh way he ruled.",limitations:"About how Americans saw Diem, more than about life in South Vietnam’s villages.",originalUrl:"https://openlibrary.org/works/OL5711648W",verificationCategory:"VERIFIED_PARAPHRASE"},"c2-3":{id:"c2-3",marker:3,citation:"Pike, Douglas. Viet Cong: The Organization and Techniques of the National Liberation Front of South Vietnam. MIT Press, 1966.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Douglas Pike",title:"Viet Cong: The Organization and Techniques of the National Liberation Front of South Vietnam",date:"1966",publicationOrArchive:"MIT Press",supportsClaim:"Explains how the National Liberation Front was organized: its secret cells, how it recruited and how it won support in the villages.",limitations:"Written by an American government official in the middle of the war, from the American side.",originalUrl:"https://openlibrary.org/works/OL4458871W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q003",chapter:2,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"Adopted at the 15th Plenum in January 1959, Resolution 15 authorized southern communist cadres to combine mass political struggle with revolutionary armed violence to overthrow the Diem government and establish revolutionary power.",source:"Resolution 15 of the Vietnam Workers’ Party Central Committee",authorOrCreator:"Central Executive Committee, Workers’ Party of Vietnam",institution:"Workers’ Party of Vietnam (Lao Dong), Hanoi",date:"January 1959",sourceUrl:"https://www.wilsoncenter.org/program/cold-war-international-history-project",locator:"CWIHP Bulletin 16/17; Van Kien Dang Toan Tap [Complete Party Documents], Vol. 20 (Hanoi: Chinh Tri Quoc Gia, 2002)",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The 1959 decision in which Hanoi’s leaders approved armed struggle in the South. It led to Group 559 and the Ho Chi Minh Trail.",limitations:"This is a Vietnamese party document, and English translations word it differently. So we describe it in our own words instead of quoting it.",conversionStatus:"converted_to_paraphrase",notes:"The substantive doctrine of Resolution 15 is verified against CWIHP and Vietnamese official party history. Kept as a verified paraphrase to prevent translation inaccuracy."},{id:"Q026",chapter:2,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"The Conference recognizes that the essential purpose of the agreement relating to Viet-Nam is to settle military questions with a view to ending hostilities and that the military demarcation line is provisional and should not in any way be interpreted as constituting a political or territorial boundary.",exactQuotation:"The Conference recognizes that the essential purpose of the agreement relating to Viet-Nam is to settle military questions with a view to ending hostilities and that the military demarcation line is provisional and should not in any way be interpreted as constituting a political or territorial boundary.",source:"Final Declaration of the Geneva Conference on the Problem of Restoring Peace in Indo-China",authorOrCreator:"Participants in the Geneva Conference",institution:"Geneva Conference on Indochina",date:"July 21, 1954",sourceUrl:"https://avalon.law.yale.edu/20th_century/inch005.asp",locator:"FRUS 1952–1954, Vol. XIII, Part 2, Document 1035, Paragraph 6 / Yale Avalon Project",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The 1954 Geneva agreement that split Vietnam at the 17th parallel. It called the line a temporary military boundary, not a border between two countries.",limitations:"The United States and the government in Saigon would not sign it. That let them argue later that it did not bind them.",conversionStatus:"verified_verbatim",notes:"Verified verbatim against Paragraph 6 of the official Final Declaration of the Geneva Conference."}]],46133);var i=e.i(46133);e.s(["citations",0,{"c3-1":{id:"c3-1",marker:1,citation:"Catton, Philip E. Diem’s Final Failure: Prelude to America’s War in Vietnam. University Press of Kansas, 2002.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Philip E. Catton",title:"Diem’s Final Failure: Prelude to America’s War in Vietnam",date:"2002",publicationOrArchive:"University Press of Kansas",supportsClaim:"Shows that Diem and his brother Nhu had their own plan for building a modern country, and that it turned both army officers and farmers against them.",limitations:"About Diem’s ideas and goals, not the details of the coup.",originalUrl:"https://openlibrary.org/works/OL8330557W",verificationCategory:"VERIFIED_PARAPHRASE"},"c3-2":{id:"c3-2",marker:2,citation:"Kaiser, David. American Tragedy: Kennedy, Johnson, and the Origins of the Vietnam War. Harvard University Press, 2000.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"David Kaiser",title:"American Tragedy: Kennedy, Johnson, and the Origins of the Vietnam War",date:"2000",publicationOrArchive:"Harvard University Press",supportsClaim:"Shows that Kennedy kept refusing to send American combat troops, even when his military chiefs pushed hard for it.",limitations:"One historian’s argument. It stresses the differences between Kennedy and Johnson, and other historians disagree.",originalUrl:"https://openlibrary.org/works/OL8104707W",verificationCategory:"VERIFIED_PARAPHRASE"},"c3-3":{id:"c3-3",marker:3,citation:"National Security Archive. Electronic Briefing Book No. 101: The Diem Coup.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"National Security Archive (John Prados, Editor)",title:"Electronic Briefing Book No. 101: The Diem Coup",date:"2003",publicationOrArchive:"George Washington University",supportsClaim:"A collection of declassified cables and White House recordings of Kennedy and his advisers talking about Cable 243 and the coup against Diem.",limitations:"The records show what was said at the time. They don’t settle the argument over who was most to blame.",originalUrl:"https://nsarchive2.gwu.edu/NSAEBB/NSAEBB101/",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q004",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"US Government cannot tolerate situation in which power lies in Nhu's hands. Diem must be given chance to rid himself of Nhu and his coterie and replace them with best military and political personalities available. If, in spite of all of your efforts, Diem remains obdurate and refuses, then we must face the possibility that Diem himself cannot be preserved.",exactQuotation:"US Government cannot tolerate situation in which power lies in Nhu's hands. Diem must be given chance to rid himself of Nhu and his coterie and replace them with best military and political personalities available. If, in spite of all of your efforts, Diem remains obdurate and refuses, then we must face the possibility that Diem himself cannot be preserved.",source:"State Department Telegram 243 to Embassy Saigon (The Coup Cable)",authorOrCreator:"Roger Hilsman, Averell Harriman, George Ball",institution:"U.S. Department of State",date:"August 24, 1963",sourceUrl:"https://history.state.gov/historicaldocuments/frus1961-63v04/d268",locator:"FRUS 1961–1963, Vol. IV, Vietnam, August–December 1963, Document 268 (Telegram 243)",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The August 1963 cable telling Ambassador Henry Cabot Lodge Jr. that Diem must get rid of his brother Nhu, and that the United States would accept a coup if he refused.",limitations:"It did not order anyone to kill Diem. Kennedy was shaken when he learned the generals had killed Diem and Nhu.",conversionStatus:"verified_verbatim",notes:"Verified verbatim against paragraph 2 of Telegram 243 in FRUS 1961–1963, Vol. IV, Document 268. Ellipses from prior draft removed in favor of unbroken paragraph text."},{id:"Q017",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"We must face the fact that the United States is neither omnipotent nor omniscient—that we are only six percent of the world's population—that we cannot impose our will upon the other ninety-four percent of mankind—that we cannot right every wrong or reverse each adversity—and that therefore there cannot be an American solution to every world problem.",exactQuotation:"We must face the fact that the United States is neither omnipotent nor omniscient—that we are only six percent of the world's population—that we cannot impose our will upon the other ninety-four percent of mankind—that we cannot right every wrong or reverse each adversity—and that therefore there cannot be an American solution to every world problem.",source:"Address at the University of Washington 100th Anniversary",authorOrCreator:"President John F. Kennedy",institution:"Executive Office of the President",date:"November 16, 1961",sourceUrl:"https://www.jfklibrary.org/asset-viewer/archives/JFKPOF/036/JFKPOF-036-015",locator:"Public Papers of the Presidents: John F. Kennedy, 1961, Item 473, pp. 725–727",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Kennedy’s November 1961 speech in Seattle, where he said the United States could not fix every problem in the world on its own.",limitations:"A different speech from his inaugural address. Don’t combine lines from the two.",conversionStatus:"verified_verbatim",notes:'Prior draft conflated this address with the January 1961 Inaugural ("pay any price"). Separated into Q017 and Q017B. Verified verbatim against JFK Library archives.'},{id:"Q017B",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"Let every nation know, whether it wishes us well or ill, that we shall pay any price, bear any burden, meet any hardship, support any friend, oppose any foe to assure the survival and the success of liberty.",exactQuotation:"Let every nation know, whether it wishes us well or ill, that we shall pay any price, bear any burden, meet any hardship, support any friend, oppose any foe to assure the survival and the success of liberty.",source:"Inaugural Address of President John F. Kennedy",authorOrCreator:"President John F. Kennedy",institution:"Executive Office of the President",date:"January 20, 1961",sourceUrl:"https://www.jfklibrary.org/asset-viewer/archives/JFKPOF/035/JFKPOF-035-041",locator:"Public Papers of the Presidents: John F. Kennedy, 1961, Item 1, pp. 1–3",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Kennedy’s inaugural address of January 1961, promising that America would defend freedom around the world.",limitations:"Given ten months before the Seattle speech. The two are separate and should be quoted separately.",conversionStatus:"verified_verbatim",notes:"Separated from Q017 to resolve prior speech conflation. Verified verbatim against JFK Library official records."},{id:"Q018",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"The troops will march in; the bands will play; the crowds will cheer; and in four days everyone will have forgotten. Then we will be told we have to send in more troops. It’s like taking a drink. The effect wears off, and you have to take another.",exactQuotation:"The troops will march in; the bands will play; the crowds will cheer; and in four days everyone will have forgotten. Then we will be told we have to send in more troops. It’s like taking a drink. The effect wears off, and you have to take another.",source:"A Thousand Days: John F. Kennedy in the White House",authorOrCreator:"Arthur M. Schlesinger Jr. quoting John F. Kennedy",institution:"White House Special Assistant / Historical Memoir",date:"November 1961 (Published 1965)",sourceUrl:"https://www.worldcat.org/title/thousand-days/oclc/245844",locator:"Houghton Mifflin, 1965, p. 547",locatorStatus:"supported",verified:!0,sourceType:"LATER_HISTORICAL_ANALYSIS",supportsClaim:"Shows that in late 1961 Kennedy doubted General Maxwell Taylor’s advice to send American combat troops to Vietnam.",limitations:"This comes from a memoir by a Kennedy aide, published four years later. It is his memory of what Kennedy said, not a recording.",conversionStatus:"verified_verbatim",notes:"Verified exact page and wording from Schlesinger (1965, p. 547). Classified as scholarly secondary source / memoir oral testimony."},{id:"Q019",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"Now we have a problem in making our power credible, and Vietnam looks like the place.",exactQuotation:"Now we have a problem in making our power credible, and Vietnam looks like the place.",source:"Interview with James Reston Following Vienna Summit",authorOrCreator:"James Reston quoting John F. Kennedy",institution:"The New York Times",date:"June 1961 (Published in Memoir 1991)",sourceUrl:"https://www.nytimes.com/",locator:"James Reston, Deadline: A Memoir (Random House, 1991, p. 291); Halberstam, The Best and the Brightest (1972, p. 76)",locatorStatus:"supported",verified:!0,sourceType:"CONTEMPORARY_REPORTING",supportsClaim:"Shows that after Kennedy’s tense meeting with Khrushchev in Vienna, he saw Vietnam as a place to prove America would stand firm.",limitations:"Kennedy said it privately to a reporter. We know it only from what the reporter and others remembered later.",conversionStatus:"verified_verbatim",notes:"Verified against Reston (1991, p. 291) and Halberstam (1972, p. 76). Slotted historically to June 1961 Vienna aftermath."},{id:"Q020",chapter:3,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"In the final analysis, it is their war. They are the ones who have to win it or lose it. We can help them, we can give them equipment, we can send our men out there as advisers, but they have to win it, the people of Viet-Nam, against the Communists.",exactQuotation:"In the final analysis, it is their war. They are the ones who have to win it or lose it. We can help them, we can give them equipment, we can send our men out there as advisers, but they have to win it, the people of Viet-Nam, against the Communists.",source:"CBS Evening News Interview with Walter Cronkite",authorOrCreator:"President John F. Kennedy",institution:"CBS News / White House",date:"September 2, 1963",sourceUrl:"https://www.jfklibrary.org/asset-viewer/archives/JFKPOF/047/JFKPOF-047-024",locator:"Public Papers of the Presidents: John F. Kennedy, 1963, Item 352, p. 652",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Kennedy on television in 1963, saying it was up to the South Vietnamese to win their own war.",limitations:"In the same interview he said the United States would not pull out its aid or advisers.",conversionStatus:"verified_verbatim",notes:"Verified verbatim against Public Papers of the Presidents: JFK, 1963, Item 352."}]],52);var o=e.i(52);e.s(["citations",0,{"c4-1":{id:"c4-1",marker:1,citation:"Moise, Edwin E. Tonkin Gulf and the Escalation of the Vietnam War. University of North Carolina Press, 1996.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Edwin E. Moise",title:"Tonkin Gulf and the Escalation of the Vietnam War",date:"1996",publicationOrArchive:"University of North Carolina Press",supportsClaim:"A detailed reconstruction of the night of August 4, showing there were no North Vietnamese boats there and that bad radar and sonar readings caused the reports.",limitations:"Moise does not say Johnson knowingly lied. He says officials acted too fast on reports that were wrong.",originalUrl:"https://openlibrary.org/works/OL13786629W",verificationCategory:"VERIFIED_PARAPHRASE"},"c4-2":{id:"c4-2",marker:2,citation:'Hanyok, Robert J. "Skunks, Bogies, Silent Hounds, and the Flying Fish: The Gulf of Tonkin Mystery." Cryptologic Quarterly, NSA, 2001.',sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Robert J. Hanyok",title:"Skunks, Bogies, Silent Hounds, and the Flying Fish: The Gulf of Tonkin Mystery, 2–4 August 1964",date:"Winter 2000 / Spring 2001 (Declassified 2005)",publicationOrArchive:"NSA Cryptologic Quarterly / National Security Archive EBB 132",locator:"Cryptologic Quarterly, Vol. 19, No. 4 / Vol. 20, No. 1",supportsClaim:"The National Security Agency’s own history of the Gulf of Tonkin. It found that the intercepted messages used as proof of an August 4 attack were really about the August 2 fight.",limitations:"It blames analysts who passed along only the evidence that fit, not top officials knowingly making up an attack.",originalUrl:"https://nsarchive2.gwu.edu/NSAEBB/NSAEBB132/",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"First, it is not simply that there is a different story as to what happened; it is that no attack happened that night."},"c4-3":{id:"c4-3",marker:3,citation:"Logevall, Fredrik. Choosing War: The Lost Chance for Peace and the Escalation of War in Vietnam. University of California Press, 1999.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Fredrik Logevall",title:"Choosing War: The Lost Chance for Peace and the Escalation of War in Vietnam",date:"1999",publicationOrArchive:"University of California Press",supportsClaim:"Shows that the Johnson administration had written a draft resolution months before the Gulf of Tonkin and used the incident to get it passed.",limitations:"About political choices in Washington and missed chances for peace, not what happened at sea.",originalUrl:"https://openlibrary.org/works/OL6211304W",verificationCategory:"VERIFIED_PARAPHRASE"},Q027:{id:"Q027",marker:4,citation:"Johnson, Lyndon B. Radio and Television Report to the American People Following Renewed Aggression in the Gulf of Tonkin. August 4, 1964.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"President Lyndon B. Johnson",title:"Radio and Television Report Following Renewed Aggression in the Gulf of Tonkin",date:"August 4, 1964 (began 11:36 p.m. EDT)",publicationOrArchive:"Primary source",locator:"Public Papers of the Presidents: Lyndon B. Johnson, 1963–64, via The American Presidency Project",supportsClaim:"Johnson on national television announcing air strikes against North Vietnam, the night of the reported second attack.",limitations:"This is the government’s version of August 4. It leaves out the doubts Captain Herrick had sent that afternoon.",originalUrl:"https://www.presidency.ucsb.edu/node/238730",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"But repeated acts of violence against the Armed Forces of the United States must be met not only with alert defense, but with positive reply. That reply is being given as I speak to you tonight."},Q028:{id:"Q028",marker:5,citation:"Johnson, Lyndon B. Remarks in Memorial Hall, Akron University. October 21, 1964.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"President Lyndon B. Johnson",title:"Remarks in Memorial Hall, Akron University",date:"October 21, 1964",publicationOrArchive:"Primary source",locator:"Public Papers of the Presidents, 1964, Book II, pp. 1391–1393, via The American Presidency Project",supportsClaim:"Johnson promising during the 1964 campaign not to send American boys to fight a war in Asia, two months after the resolution gave him the power to do it.",limitations:"A campaign speech meant to set him apart from Barry Goldwater. It doesn’t show what his government was planning.",originalUrl:"https://www.presidency.ucsb.edu/documents/remarks-memorial-hall-akron-university",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"But we are not about to send American boys 9 or 10,000 miles away from home to do what Asian boys ought to be doing for themselves."},Q029:{id:"Q029",marker:6,citation:"War Powers Resolution, Pub. L. 93–148, § 2(c), 87 Stat. 555 (1973); 50 U.S.C. § 1541(c).",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"93rd United States Congress",title:"War Powers Resolution, Section 2(c)",date:"November 7, 1973",publicationOrArchive:"Primary source",locator:"Pub. L. 93–148, § 2(c), 87 Stat. 555; 50 U.S.C. § 1541(c)",supportsClaim:"The War Powers Resolution of 1973. It lists the three situations in which a president may send troops into combat, and it was written because of Vietnam.",limitations:"Congress passed it over Nixon’s veto. Later presidents have argued it goes too far and have not always followed it.",originalUrl:"https://www.law.cornell.edu/uscode/text/50/1541",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"The constitutional powers of the President as Commander-in-Chief to introduce United States Armed Forces into hostilities, or into situations where imminent involvement in hostilities is clearly indicated by the circumstances, are exercised only pursuant to (1) a declaration of war, (2) specific statutory authorization, or (3) a national emergency created by attack upon the United States, its territories or possessions, or its armed forces."}},"sources",0,[{id:"Q005",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"First, it is not simply that there is a different story as to what happened; it is that no attack happened that night.",exactQuotation:"First, it is not simply that there is a different story as to what happened; it is that no attack happened that night.",source:'NSA Cryptologic Quarterly: "Skunks, Bogies, Silent Hounds, and the Flying Fish: The Gulf of Tonkin Mystery, 2–4 August 1964"',authorOrCreator:"Robert J. Hanyok",institution:"National Security Agency (Center for Cryptologic History)",date:"Winter 2000 / Spring 2001 (Declassified 2005)",sourceUrl:"https://nsarchive2.gwu.edu/NSAEBB/NSAEBB132/",locator:"Cryptologic Quarterly, Vol. 19, No. 4 / Vol. 20, No. 1, p. 1 / NSA-EBB-132",locatorStatus:"supported",verified:!0,sourceType:"LATER_HISTORICAL_ANALYSIS",supportsClaim:"The National Security Agency’s own history of the Gulf of Tonkin. It found that the intercepted messages used as proof of an August 4 attack were really about the August 2 fight.",limitations:"It blames analysts who passed along only the evidence that fit, not top officials knowingly making up an attack.",conversionStatus:"verified_verbatim",notes:"Prior site draft combined sentences across pages 1, 3, and 56 into a single quotation. Now verified verbatim to page 1 exact thesis sentence. Secondary analytical findings preserved as documented context."},{id:"Q006",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"Resolved by the Senate and House of Representatives of the United States of America in Congress assembled, That the Congress approves and supports the determination of the President, as Commander in Chief, to take all necessary measures to repel any armed attack against the forces of the United States and to prevent further aggression.",exactQuotation:"Resolved by the Senate and House of Representatives of the United States of America in Congress assembled, That the Congress approves and supports the determination of the President, as Commander in Chief, to take all necessary measures to repel any armed attack against the forces of the United States and to prevent further aggression.",source:"Joint Resolution of Congress, Public Law 88-408 (The Gulf of Tonkin Resolution)",authorOrCreator:"88th United States Congress",institution:"United States Congress",date:"August 7, 1964 (Passed) / August 10, 1964 (Enacted)",sourceUrl:"https://www.archives.gov/milestone-documents/tonkin-gulf-resolution",locator:"78 Stat. 384, Section 1 / Public Law 88-408",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The 1964 Gulf of Tonkin Resolution, which let President Johnson use military force in Southeast Asia without a declaration of war.",limitations:"It passed 416 to 0 in the House and 88 to 2 in the Senate. Congress voted after being told the ships had been attacked without reason.",conversionStatus:"verified_verbatim",notes:"Verified letter-for-letter against the United States Statutes at Large, 78 Stat. 384, Section 1."},{id:"Q013",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"Review of action makes many reported contacts and torpedoes fired appear doubtful. Freak weather effects on radar and overeager sonarmen may have accounted for many reports. No actual visual sightings by Maddox. Suggest complete evaluation before any further action taken.",exactQuotation:"Review of action makes many reported contacts and torpedoes fired appear doubtful. Freak weather effects on radar and overeager sonarmen may have accounted for many reports. No actual visual sightings by Maddox. Suggest complete evaluation before any further action taken.",source:"Flash Telegram 041727Z AUG 64 from CTG 72.1 to CINCPACFLT",authorOrCreator:"Captain John J. Herrick (Commander, Task Group 72.1)",institution:"U.S. Navy, Commander Task Group 72.1 (USS Maddox)",date:"August 4, 1964 (1:27 PM EDT / 12:27 AM Aug 5 Gulf time, UTC+7)",sourceUrl:"https://history.state.gov/historicaldocuments/frus1964-68v01/d117",locator:"FRUS 1964–1968, Vol. I, Vietnam, Document 117 (Telegram 041727Z)",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The cable in which the commander at sea, Captain John Herrick, warned Washington that the August 4 attack looked doubtful. It arrived hours before Johnson went on television.",limitations:"Herrick was not sure no attack had happened. He reported confusing radar and sonar readings and asked for a full review.",conversionStatus:"verified_verbatim",notes:"Verified verbatim against Telegram 041727Z in FRUS 1964–1968, Vol. I, Document 117. Replaces prior draft’s informal ellipses."},{id:"Q021",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"I had the best seat in the house to watch that event, and our destroyers were just shooting at phantom targets—there were no PT boats there... There was nothing there but black water and American firepower.",exactQuotation:"I had the best seat in the house to watch that event, and our destroyers were just shooting at phantom targets—there were no PT boats there... There was nothing there but black water and American firepower.",source:"In Love and War: The Story of a Family’s Ordeal and Sacrifice During the Vietnam Years",authorOrCreator:"Commander James B. Stockdale",institution:"U.S. Navy / Carrier Air Wing 16 (USS Ticonderoga)",date:"1984",sourceUrl:"https://www.worldcat.org/title/in-love-and-war/oclc/10751939",locator:"Harper & Row, 1984, Chapter 6, p. 118",locatorStatus:"supported",verified:!0,sourceType:"LATER_HISTORICAL_ANALYSIS",supportsClaim:"James Stockdale, a Navy pilot flying overhead on August 4, says he saw the destroyers firing but no enemy boats.",limitations:"He wrote this in a memoir twenty years later, and he could see only so much at night in bad weather. It matches the doubts Herrick reported that night.",conversionStatus:"verified_verbatim",notes:"Verified exact page and wording from Stockdale (1984, p. 118). Replaces prior draft’s synthetic phrase."},{id:"Q022",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"I believe that history will record that we have made a great mistake in subverting and circumventing the Constitution of the United States. . . I believe this resolution to be a historic mistake.",exactQuotation:"I believe that history will record that we have made a great mistake in subverting and circumventing the Constitution of the United States. . . I believe this resolution to be a historic mistake.",source:"Congressional Record — Senate Floor Debate on Gulf of Tonkin Resolution",authorOrCreator:"Senator Wayne Morse (D-OR)",institution:"United States Senate",date:"August 7, 1964",sourceUrl:"https://www.congress.gov/",locator:"Congressional Record, 88th Cong., 2nd Sess., Vol. 110, Part 14, pp. 18470–18471",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Senate debate in which Wayne Morse warned that the resolution handed Congress’s power to make war to the president, based on claims nobody had checked.",limitations:"Morse and Ernest Gruening were the only two senators to vote no. 88 voted yes.",conversionStatus:"verified_verbatim",notes:'Prior site draft misquoted "great mistake" as "grave mistake" and dropped "and circumventing". Verified against Congressional Record, Vol. 110, Part 14.'},{id:"Q023",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"It was just confusion, and events afterward showed that our judgment that we’d been attacked that day was wrong. It didn’t happen.",exactQuotation:"It was just confusion, and events afterward showed that our judgment that we’d been attacked that day was wrong. It didn’t happen.",source:"The Fog of War: Eleven Lessons from the Life of Robert S. McNamara",authorOrCreator:"Robert S. McNamara (Directed by Errol Morris)",institution:"Sony Pictures Classics / Documentary Record",date:"2003",sourceUrl:"https://www.sonyclassics.com/fogofwar/",locator:'The Fog of War film transcript, Lesson #4 ("Belief and Seeing")',locatorStatus:"supported",verified:!0,sourceType:"LATER_HISTORICAL_ANALYSIS",supportsClaim:"Robert McNamara, Johnson’s secretary of defense, admitting years later that the August 4 attack did not happen.",limitations:"An interview filmed about forty years later. It shows what he thought looking back, not what he thought in 1964.",conversionStatus:"verified_verbatim",notes:"Verified verbatim against the official film transcript of The Fog of War (2003)."},{id:"Q024",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"AM BEING APPROACHED BY HIGH SPEED CRAFT WITH APPARENT INTENTION OF TORPEDO ATTACK. INTEND TO OPEN FIRE IF NECESSARY SELF DEFENSE.",exactQuotation:"AM BEING APPROACHED BY HIGH SPEED CRAFT WITH APPARENT INTENTION OF TORPEDO ATTACK. INTEND TO OPEN FIRE IF NECESSARY SELF DEFENSE.",source:"USS Maddox (DD-731) Operational Flash Message (August 2, 1964)",authorOrCreator:"Captain John J. Herrick / Commanding Officer USS Maddox",institution:"U.S. Navy, Task Group 72.1",date:"August 2, 1964 (DTG 020640Z)",sourceUrl:"https://www.history.navy.mil/",locator:"Naval History and Heritage Command, Tonkin Gulf Message Traffic, DTG 020640Z AUG 64",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The message the USS Maddox sent on August 2, 1964, reporting North Vietnamese torpedo boats closing in.",limitations:"It is about the real daylight fight on August 2, not the disputed night of August 4.",conversionStatus:"verified_verbatim",notes:"Replaces the previous site draft’s synthetic simulated cable with the authentic naval flash message verified in Naval History and Heritage Command records."},{id:"Q027",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"But repeated acts of violence against the Armed Forces of the United States must be met not only with alert defense, but with positive reply. That reply is being given as I speak to you tonight.",exactQuotation:"But repeated acts of violence against the Armed Forces of the United States must be met not only with alert defense, but with positive reply. That reply is being given as I speak to you tonight.",source:"Radio and Television Report to the American People Following Renewed Aggression in the Gulf of Tonkin",authorOrCreator:"President Lyndon B. Johnson",institution:"The White House",date:"August 4, 1964 (began 11:36 p.m. EDT)",sourceUrl:"https://www.presidency.ucsb.edu/node/238730",locator:"Public Papers of the Presidents: Lyndon B. Johnson, 1963–64, via The American Presidency Project",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Johnson on national television announcing air strikes against North Vietnam, the night of the reported second attack.",limitations:"This is the government’s version of August 4. It leaves out the doubts Captain Herrick had sent that afternoon.",conversionStatus:"verified_verbatim",notes:"Verified letter-for-letter against the American Presidency Project transcript, which notes the president began speaking at 11:36 p.m. EDT."},{id:"Q028",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"But we are not about to send American boys 9 or 10,000 miles away from home to do what Asian boys ought to be doing for themselves.",exactQuotation:"But we are not about to send American boys 9 or 10,000 miles away from home to do what Asian boys ought to be doing for themselves.",source:"Remarks in Memorial Hall, Akron University",authorOrCreator:"President Lyndon B. Johnson",institution:"Presidential campaign remarks",date:"October 21, 1964",sourceUrl:"https://www.presidency.ucsb.edu/documents/remarks-memorial-hall-akron-university",locator:"Public Papers of the Presidents, 1964, Book II, pp. 1391–1393, via The American Presidency Project",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Johnson promising during the 1964 campaign not to send American boys to fight a war in Asia, two months after the resolution gave him the power to do it.",limitations:"A campaign speech meant to set him apart from Barry Goldwater. It doesn’t show what his government was planning.",conversionStatus:"verified_verbatim",notes:"Verified against the American Presidency Project transcript. Replaces an unregistered variant (“nine or ten thousand miles”) previously shown in the chapter."},{id:"Q029",chapter:4,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"The constitutional powers of the President as Commander-in-Chief to introduce United States Armed Forces into hostilities, or into situations where imminent involvement in hostilities is clearly indicated by the circumstances, are exercised only pursuant to (1) a declaration of war, (2) specific statutory authorization, or (3) a national emergency created by attack upon the United States, its territories or possessions, or its armed forces.",exactQuotation:"The constitutional powers of the President as Commander-in-Chief to introduce United States Armed Forces into hostilities, or into situations where imminent involvement in hostilities is clearly indicated by the circumstances, are exercised only pursuant to (1) a declaration of war, (2) specific statutory authorization, or (3) a national emergency created by attack upon the United States, its territories or possessions, or its armed forces.",source:"War Powers Resolution, Section 2(c) (50 U.S.C. § 1541(c))",authorOrCreator:"93rd United States Congress",institution:"United States Congress",date:"November 7, 1973",sourceUrl:"https://www.law.cornell.edu/uscode/text/50/1541",locator:"Pub. L. 93–148, § 2(c), 87 Stat. 555; 50 U.S.C. § 1541(c)",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"The War Powers Resolution of 1973. It lists the three situations in which a president may send troops into combat, and it was written because of Vietnam.",limitations:"Congress passed it over Nixon’s veto. Later presidents have argued it goes too far and have not always followed it.",conversionStatus:"verified_verbatim",notes:"Verified letter-for-letter against the U.S. Code text published by the Legal Information Institute (Cornell)."}]],35049);var a=e.i(35049);e.s(["citations",0,{"c5-1":{id:"c5-1",marker:1,citation:"Nguyen, Lien-Hang T. Hanoi’s War: An International History of the War for Peace in Vietnam. University of North Carolina Press, 2012.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Lien-Hang T. Nguyen",title:"Hanoi’s War: An International History of the War for Peace in Vietnam",date:"2012",publicationOrArchive:"University of North Carolina Press",supportsClaim:"Shows the fight inside Hanoi’s leadership, as Le Duan’s side pushed out more cautious leaders like Giap and arrested others.",limitations:"About North Vietnam’s leaders and diplomacy, not the fighting with American troops.",originalUrl:"https://openlibrary.org/works/OL16416536W",verificationCategory:"VERIFIED_PARAPHRASE"},"c5-2":{id:"c5-2",marker:2,citation:"Lewy, Guenter. America in Vietnam. Oxford University Press, 1978.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Guenter Lewy",title:"America in Vietnam",date:"1978",publicationOrArchive:"Oxford University Press",supportsClaim:"Looks closely at American firepower, the plan to wear the enemy down, and the body counts used to measure progress under Westmoreland.",limitations:"Lewy is a revisionist, and his book relies mostly on U.S. military records.",originalUrl:"https://openlibrary.org/works/OL115968W",verificationCategory:"VERIFIED_PARAPHRASE"},"c5-3":{id:"c5-3",marker:3,citation:"Appy, Christian G. Working-Class War: American Combat Soldiers and Vietnam. University of North Carolina Press, 1993.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Christian G. Appy",title:"Working-Class War: American Combat Soldiers and Vietnam",date:"1993",publicationOrArchive:"University of North Carolina Press",supportsClaim:"Shows who was drafted and who did the fighting. Young men from working-class families carried far more of the combat than others.",limitations:"About American soldiers’ lives, told partly through interviews, not about decisions at the top.",originalUrl:"https://openlibrary.org/works/OL4291010W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q007",chapter:5,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"A declassified July 18, 1966 CIA intelligence memorandum reported evidence of tactical debate within Hanoi’s leadership between General Nguyen Chi Thanh (who advocated aggressive, large-unit conventional engagements to blunt American combat forces) and Defense Minister Vo Nguyen Giap (who urged force preservation, prolonged attrition, and decentralized guerrilla tactics).",source:"CIA Intelligence Memorandum: The Strategy Debate in Hanoi",authorOrCreator:"Directorate of Intelligence, Central Intelligence Agency",institution:"Central Intelligence Agency, Office of Current Intelligence",date:"July 18, 1966",sourceUrl:"https://www.cia.gov/readingroom/document/cia-rdp79t00826a001100010046-3",locator:"CIA Freedom of Information Act Electronic Reading Room, Document CIA-RDP79T00826A001100010046-3",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"A 1966 CIA report showing that American intelligence knew North Vietnam’s generals disagreed about how to fight the war.",limitations:"The CIA based it on North Vietnamese radio and party magazines. We describe it in our own words instead of quoting it.",conversionStatus:"converted_to_paraphrase",notes:"Confirmed in CIA CREST reading room. Maintained strictly as an analytical paraphrase."},{id:"Q008",chapter:5,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"In her May 1968 eyewitness report from Hanoi, author Mary McCarthy reported observing individual cylindrical precast concrete bomb shelters sunk along sidewalks and widespread evacuation of children and the elderly to rural villages, noting that aerial bombardment had reinforced civilian social mobilization and collective discipline rather than causing urban collapse.",source:'"Hanoi—1968" (Eyewitness Dispatch from North Vietnam)',authorOrCreator:"Mary McCarthy",institution:"The New York Review of Books",date:"May 23, 1968",sourceUrl:"https://www.nybooks.com/articles/1968/05/23/hanoi-1968/",locator:"The New York Review of Books, Vol. 10, No. 10, pp. 5–18 / McCarthy, Hanoi (Harcourt, Brace & World, 1968)",locatorStatus:"supported",verified:!0,sourceType:"CONTEMPORARY_REPORTING",supportsClaim:"Mary McCarthy’s 1968 visit to Hanoi, describing how the city kept going under American bombing.",limitations:"Her hosts chose where she could go. We describe her account in our own words instead of quoting it.",conversionStatus:"converted_to_paraphrase",notes:"Verified that the underlying observations match McCarthy’s published report. Quotation marks permanently removed."}]],9212);var r=e.i(9212);e.s(["citations",0,{"c6-1":{id:"c6-1",marker:4,citation:"Pike, Douglas. Viet Cong: The Organization and Techniques of the National Liberation Front of South Vietnam. MIT Press, 1966.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Douglas Pike",title:"Viet Cong: The Organization and Techniques of the National Liberation Front of South Vietnam",date:"1966",publicationOrArchive:"MIT Press",supportsClaim:"Explains how the National Liberation Front was organized, including the hidden government it ran in the villages and how it recruited.",limitations:"Written by an American government official in the middle of the war, from the American side.",originalUrl:"https://openlibrary.org/works/OL4458871W",verificationCategory:"VERIFIED_PARAPHRASE"},"c6-2":{id:"c6-2",marker:2,citation:"Buckingham, William A. Operation Ranch Hand: The Air Force and Herbicides in Southeast Asia, 1961–1971. Office of Air Force History, 1982.",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"William A. Buckingham",title:"Operation Ranch Hand: The Air Force and Herbicides in Southeast Asia, 1961–1971",date:"1982",publicationOrArchive:"Office of Air Force History, U.S. Air Force",supportsClaim:"The Air Force’s own history of Operation Ranch Hand: why it sprayed plant-killing chemicals over South Vietnam and how much it sprayed.",limitations:"An official history about the flying. It says little about the long-term harm to people and the land.",originalUrl:"https://openlibrary.org/works/OL6443208W",verificationCategory:"VERIFIED_PARAPHRASE"},"c6-3":{id:"c6-3",marker:3,citation:"U.S. Congress, House Committee on Government Operations. U.S. Assistance Programs in Vietnam (Hearings on the Phoenix Program). 92nd Cong., 1st sess., 1971.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"House Committee on Government Operations",title:"U.S. Assistance Programs in Vietnam (Hearings on the Phoenix Program)",date:"July 1971",publicationOrArchive:"U.S. Government Printing Office, 92nd Congress",supportsClaim:"Hearings in Congress in 1971, with sworn testimony about how the Phoenix Program worked and the abuses it was accused of.",limitations:"Witnesses disagreed about how many civilians were killed and how carefully suspects were identified.",verificationCategory:"VERIFIED_PARAPHRASE"},"c6-4":{id:"c6-4",marker:1,citation:"Leary, William M. “CIA Air Operations in Laos, 1955–1974.” Studies in Intelligence, Winter 1999–2000.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"William M. Leary",title:"CIA Air Operations in Laos, 1955–1974",date:"1999",publicationOrArchive:"Studies in Intelligence (Central Intelligence Agency)",supportsClaim:"Describes how the CIA armed Hmong fighters under Vang Pao. It reports that 20,000 were armed by the end of 1963 and describes their raids and ambushes.",limitations:"Published in the CIA’s own journal, and mostly about air operations.",originalUrl:"https://www.cia.gov/resources/csi/static/CIA-Air-Ops-Laos.pdf",verificationCategory:"VERIFIED_PARAPHRASE"},"c6-5":{id:"c6-5",marker:5,citation:"Al Jazeera. “US ‘Secret War’ remembered as Secretary of Defense Lloyd Austin visits Laos.” November 21, 2024.",sourceType:"REFERENCE_SOURCE",authorOrInstitution:"Al Jazeera",title:"US ‘Secret War’ remembered as Secretary of Defense Lloyd Austin visits Laos",date:"November 21, 2024",publicationOrArchive:"Al Jazeera",supportsClaim:"States that Laos became the most heavily bombed country per person in history.",limitations:"A news report written fifty years later. It states the ranking without showing how it was worked out.",originalUrl:"https://www.aljazeera.com/news/2024/11/21/us-secret-war-remembered-as-secretary-of-defense-lloyd-austin-visits-laos",verificationCategory:"VERIFIED_PARAPHRASE"},"c6-6":{id:"c6-6",marker:6,citation:"Institute of Medicine. Post-Vietnam Dioxin Exposure in Agent Orange–Contaminated C-123 Aircraft. National Academies Press, 2015.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Institute of Medicine",title:"Post-Vietnam Dioxin Exposure in Agent Orange–Contaminated C-123 Aircraft",date:"2015",publicationOrArchive:"National Academies Press",locator:"Chapter 1, pp. 11–12",supportsClaim:"Reports that Air Force reservists trained and worked on former spray planes in the United States from 1972 to 1982, and were exposed to dioxin.",limitations:"The committee found too little test data to say exactly how much dioxin they were exposed to.",originalUrl:"https://www.nationalacademies.org/read/18848/chapter/3",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[]],31408);var n=e.i(31408);e.s(["citations",0,{"c7-1":{id:"c7-1",marker:1,citation:"Oberdorfer, Don. Tet!: The Turning Point in the Vietnam War. Doubleday, 1971.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Don Oberdorfer",title:"Tet!: The Turning Point in the Vietnam War",date:"1971",publicationOrArchive:"Doubleday / Johns Hopkins University Press",supportsClaim:"A reporter’s classic account of the Tet Offensive and how it shook American leaders and the public.",limitations:"Written in 1971, before North Vietnamese records were available, so it tells mostly the American and South Vietnamese side.",originalUrl:"https://openlibrary.org/works/OL2261363W",verificationCategory:"VERIFIED_PARAPHRASE"},"c7-2":{id:"c7-2",marker:2,citation:"Schmitz, David F. The Tet Offensive: Politics, War, and Public Opinion. Rowman & Littlefield, 2005.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"David F. Schmitz",title:"The Tet Offensive: Politics, War, and Public Opinion",date:"2005",publicationOrArchive:"Rowman & Littlefield",supportsClaim:"Shows how Tet wrecked the Johnson administration’s claims of progress and widened the credibility gap with the public.",limitations:"About politics and the news at home, not the street fighting in Hue or Saigon.",originalUrl:"https://openlibrary.org/works/OL1943056W",verificationCategory:"VERIFIED_PARAPHRASE"},"c7-3":{id:"c7-3",marker:3,citation:"Spector, Ronald H. After Tet: The Bloodiest Year in Vietnam. Free Press, 1993.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Ronald H. Spector",title:"After Tet: The Bloodiest Year in Vietnam",date:"1993",publicationOrArchive:"The Free Press",supportsClaim:"Covers the fighting in the rest of 1968, the year both sides lost the most soldiers of the whole war.",limitations:"About the fighting, not the early peace talks in Paris.",originalUrl:"https://openlibrary.org/works/OL3935951W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q009",chapter:7,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"Adopted in late 1967, Hanoi’s Central Committee Resolution 14 formulated the operational doctrine for the Tet Offensive, calling for synchronized assaults against southern urban administrative centers and military headquarters under the strategic assumption that the strikes would trigger a spontaneous urban general uprising (Khoi Nghia) and collapse the Saigon government.",source:"Hanoi Politburo Strategic Resolution on the General Offensive (Resolution 14)",authorOrCreator:"Central Committee & Military Commission, Workers’ Party of Vietnam",institution:"Workers’ Party of Vietnam (Lao Dong), Hanoi",date:"December 1967 (Adopted January 1968)",sourceUrl:"https://www.kansaspress.ku.edu/9780700611751/",locator:"Military History Institute of Vietnam, Victory in Vietnam: The Official History of the People’s Army of Vietnam, 1954–1975, pp. 211–218",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Hanoi’s official plan for the Tet Offensive. It shows the leaders expected the people of the southern cities to rise up, and they did not.",limitations:"A translated military document. We describe it in our own words instead of quoting it.",conversionStatus:"converted_to_paraphrase",notes:"Underlying operational doctrine confirmed against official PAVN history and scholarly monographs (Asselin, Nguyen)."},{id:"Q014",chapter:7,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"To say that we are closer to victory today is to believe, in the face of the evidence, the optimists who have been wrong in the past. To suggest we are on the edge of defeat is to yield to unreasonable pessimism. To say that we are mired in stalemate seems the only realistic, yet unsatisfactory, conclusion.",exactQuotation:"To say that we are closer to victory today is to believe, in the face of the evidence, the optimists who have been wrong in the past. To suggest we are on the edge of defeat is to yield to unreasonable pessimism. To say that we are mired in stalemate seems the only realistic, yet unsatisfactory, conclusion.",source:'CBS News Special Report: "Who, What, When, Where, Why: Report from Vietnam"',authorOrCreator:"Walter Cronkite",institution:"CBS News",date:"February 27, 1968",sourceUrl:"https://www.digitalhistory.uh.edu/active_learning/explorations/vietnam/cronkite.cfm",locator:"Broadcast transcript as reprinted in Reporting Vietnam, Part One: American Journalism 1959–1969 (Library of America, 1998), pp. 581–582",locatorStatus:"supported",verified:!0,sourceType:"CONTEMPORARY_REPORTING",supportsClaim:"Walter Cronkite’s closing words on CBS in February 1968, after he went to Vietnam to see the war for himself following Tet.",limitations:"A famous line, What the hell is going on?, is often credited to him on air. He never said it in the broadcast.",conversionStatus:"verified_verbatim",notes:'Verified verbatim against CBS News broadcast transcript. Separated from Q014B oral folklore. Corrected Oct 2026: removed an added "that" and restored the comma after "unsatisfactory" to match the transcript reprinted in Reporting Vietnam (via Digital History); the earlier CBS News URL no longer resolves.'},{id:"Q014B",chapter:7,type:"claim",verificationCategory:"UNVERIFIABLE",text:'Oral newsroom folklore long attributed to Walter Cronkite the exclamation: "What the hell is going on? I thought we were winning this war!" upon seeing wire copy of the Viet Cong breaching the U.S. Embassy in Saigon.',source:"Attributed CBS Newsroom Oral Folklore",authorOrCreator:"Oral Hearsay Attributed to Walter Cronkite",institution:"CBS News Newsroom Folklore",date:"January 31, 1968",sourceUrl:"https://www.cbsnews.com/news/walter-cronkite-vietnam-editorial-tet-offensive/",locator:"Oral history hearsay; not present in contemporaneous logs or broadcast transcripts",locatorStatus:"unsupported",verified:!1,sourceType:"REFERENCE_SOURCE",supportsClaim:"Shows how shocked American newsrooms were when they heard about the attack on the U.S. Embassy in Saigon.",limitations:"This is a story people told later, with no record behind it. It is often wrongly treated as part of Cronkite’s broadcast, and we don’t quote it.",conversionStatus:"unverifiable_unsupported",notes:"Permanently cataloged as unverifiable newsroom folklore and separated from the verified on-air broadcast (Q014)."},{id:"Q025",chapter:7,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"‘It became necessary to destroy the town to save it,’ a United States major said today.",exactQuotation:"‘It became necessary to destroy the town to save it,’ a United States major said today.",source:"Associated Press Wire Dispatch from Ben Tre, South Vietnam",authorOrCreator:"Peter Arnett quoting an unnamed U.S. Army Major",institution:"The Associated Press",date:"February 7, 1968",sourceUrl:"https://apnews.com/",locator:"The New York Times, February 8, 1968, p. 14 / AP Wire Archive, Feb 7, 1968",locatorStatus:"supported",verified:!0,sourceType:"CONTEMPORARY_REPORTING",supportsClaim:"Peter Arnett’s 1968 news report from Ben Tre, quoting an American officer on why so much of the town was destroyed to retake it.",limitations:"The officer was never named. People still argue about who he was and whether his words described the whole war or just that day.",conversionStatus:"verified_verbatim",notes:"Verified against Peter Arnett’s published AP wire dispatch in The New York Times, Feb 8, 1968, p. 14."}]],71271);var s=e.i(71271);e.s(["citations",0,{"c8-1":{id:"c8-1",marker:1,citation:"Kimball, Jeffrey. Nixon’s Vietnam War. University Press of Kansas, 1998.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Jeffrey Kimball",title:"Nixon’s Vietnam War",date:"1998",publicationOrArchive:"University Press of Kansas",supportsClaim:"Explains Nixon’s plan for Vietnamization and his madman theory: pulling troops out while bombing harder, to push Hanoi into a deal.",limitations:"About decisions in the White House, not what was happening inside South Vietnam.",originalUrl:"https://openlibrary.org/works/OL1882273W",verificationCategory:"VERIFIED_PARAPHRASE"},"c8-2":{id:"c8-2",marker:2,citation:"Sorley, Lewis. A Better War: The Unexamined Victories and Final Tragedy of America’s Last Years in Vietnam. Harcourt, 1999.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Lewis Sorley",title:"A Better War: The Unexamined Victories and Final Tragedy of America’s Last Years in Vietnam",date:"1999",publicationOrArchive:"Harcourt, Inc.",supportsClaim:"Argues that General Creighton Abrams changed the way the war was fought and was making the countryside safer.",limitations:"Many historians disagree. They say Sorley overstates the progress and plays down how weak South Vietnam’s government was.",originalUrl:"https://openlibrary.org/works/OL111810W",verificationCategory:"VERIFIED_PARAPHRASE"},"c8-3":{id:"c8-3",marker:3,citation:"Willbanks, James H. A Raid Too Far: Operation Lam Son 719 and Vietnamization in Laos. Texas A&M University Press, 2014.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"James H. Willbanks",title:"A Raid Too Far: Operation Lam Son 719 and Vietnamization in Laos",date:"2014",publicationOrArchive:"Texas A&M University Press",supportsClaim:"A detailed study of Lam Son 719, the 1971 push into Laos, showing how South Vietnam’s army struggled without American advisers beside it.",limitations:"About one operation in 1971, not the whole air war.",originalUrl:"https://openlibrary.org/works/OL23301241W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[]],42069);var h=e.i(42069);e.s(["citations",0,{"c9-1":{id:"c9-1",marker:1,citation:"Asselin, Pierre. A Bitter Peace: Washington, Hanoi, and the Making of the Paris Agreement. University of North Carolina Press, 2002.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Pierre Asselin",title:"A Bitter Peace: Washington, Hanoi, and the Making of the Paris Agreement",date:"2002",publicationOrArchive:"University of North Carolina Press",supportsClaim:"Covers four years of secret talks in Paris, and why Washington agreed to let 150,000 to 200,000 North Vietnamese troops stay in the South.",limitations:"About the talks between Kissinger and Le Duc Tho, not the Christmas Bombing itself.",originalUrl:"https://openlibrary.org/works/OL5953068W",verificationCategory:"VERIFIED_PARAPHRASE"},"c9-2":{id:"c9-2",marker:2,citation:"Hung, Nguyen Tien, and Jerrold L. Schecter. The Palace File: The Secret Correspondence of Nixon, Ford, and Thieu. Harper & Row, 1986.",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Nguyen Tien Hung and Jerrold L. Schecter",title:"The Palace File: The Secret Correspondence of Nixon, Ford, and Thieu",date:"1986",publicationOrArchive:"Harper & Row",supportsClaim:"Publishes Nixon’s secret letters to Thieu promising to strike back hard if Hanoi broke the peace deal.",limitations:"Congress never saw these letters, and soon passed a law that made it illegal to keep the promise.",originalUrl:"https://openlibrary.org/works/OL4266043W",verificationCategory:"VERIFIED_PARAPHRASE"},"c9-3":{id:"c9-3",marker:3,citation:"United States Treaties and Other International Agreements, Vol. 24, Pt. 1 (1973). Agreement on Ending the War and Restoring Peace in Viet-Nam.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"U.S. Department of State / Signatory Nations",title:"Agreement on Ending the War and Restoring Peace in Viet-Nam (Paris Peace Accords)",date:"January 27, 1973",publicationOrArchive:"24 UST 1; TIAS 7542; UNTS Vol. 935",locator:"Articles 1, 2, 3(b) and 15",supportsClaim:"The text of the Paris Peace Accords: the ceasefire, the 60-day American pullout, the exchange of prisoners and the line at the 17th parallel.",limitations:"The words on paper. Within months, both North and South were breaking the ceasefire.",originalUrl:"https://treaties.un.org/doc/Publication/UNTS/Volume%20935/v935.pdf",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"The United States and all other countries respect the independence, sovereignty, unity, and territorial integrity of Viet-Nam as recognized by the 1954 Geneva Agreements on Viet-Nam."},"c9-4":{id:"c9-4",marker:4,citation:"Tagg, Lori S. “Operation Homecoming: Repatriation of American prisoners of war in Vietnam described.” U.S. Army, December 30, 2015.",sourceType:"REFERENCE_SOURCE",authorOrInstitution:"Lori S. Tagg, U.S. Army",title:"Operation Homecoming: Repatriation of American prisoners of war in Vietnam described",date:"December 30, 2015",publicationOrArchive:"U.S. Army (army.mil)",supportsClaim:"Reports that from February through March 1973 North Vietnam released 566 American military personnel, and that 25 civilians also came home.",limitations:"A later summary. It does not say when the last combat troops left.",originalUrl:"https://www.army.mil/article/160491/Operation_HOMECOMING__Repatriation_of_American_prisoners_of_war_in_Vietnam_described",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q010",chapter:9,type:"quotation",verificationCategory:"VERIFIED_QUOTATION",text:"The United States and all other countries respect the independence, sovereignty, unity, and territorial integrity of Viet-Nam as recognized by the 1954 Geneva Agreements on Viet-Nam.",exactQuotation:"The United States and all other countries respect the independence, sovereignty, unity, and territorial integrity of Viet-Nam as recognized by the 1954 Geneva Agreements on Viet-Nam.",source:"Agreement on Ending the War and Restoring Peace in Viet-Nam (The Paris Peace Accords)",authorOrCreator:"William P. Rogers, Nguyen Duy Trinh, Tran Van Lam, Nguyen Thi Binh",institution:"Governments of the United States, DRV, RVN, and PRG",date:"January 27, 1973",sourceUrl:"https://treaties.un.org/doc/Publication/UNTS/Volume%20935/v935.pdf",locator:"United Nations Treaty Series (UNTS), Vol. 935, No. 13295, Chapter I, Article 1, p. 4",locatorStatus:"supported",verified:!0,sourceType:"PRIMARY_SOURCE",supportsClaim:"Article 1 of the 1973 Paris Peace Accords, in which the United States promised to respect Vietnam’s independence and unity as recognized at Geneva in 1954.",limitations:"Only Article 1 is quoted exactly. The chapter describes the other articles in its own words.",conversionStatus:"verified_verbatim",notes:"Verified letter-for-letter against UNTS Vol. 935, Chapter I, Article 1."},{id:"Q015",chapter:9,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"In his scholarly study A Bitter Peace, historian Pierre Asselin highlighted that the critical strategic concession of the Paris Accords was permitting an estimated 150,000 to 200,000 North Vietnamese combat troops to remain in place in South Vietnam while requiring the complete withdrawal of all American combat forces.",source:"A Bitter Peace: Washington, Hanoi, and the Making of the Paris Agreement",authorOrCreator:"Pierre Asselin",institution:"University of North Carolina Press / Scholarly Monograph",date:"2002",sourceUrl:"https://uncpress.org/book/9780807854174/a-bitter-peace/",locator:"UNC Press, 2002, Chapter 6, pp. 165–172",locatorStatus:"supported",verified:!0,sourceType:"SCHOLARLY_SECONDARY_SOURCE",supportsClaim:"Explains why South Vietnam’s President Thieu saw the Paris Accords as a deal that would doom his country.",limitations:"This is our summary of Asselin’s argument. A line often shown as his quotation is not his exact words, so we don’t quote it.",conversionStatus:"converted_to_paraphrase",notes:"Verified that the substantive argument matches Asselin (2002, pp. 165–172). Maintained as an analytical paraphrase."}]],74972);var l=e.i(74972);e.s(["citations",0,{"c10-1":{id:"c10-1",marker:1,citation:"Veith, George J. Black April: The Fall of South Vietnam, 1973–1975. Encounter Books, 2012.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"George J. Veith",title:"Black April: The Fall of South Vietnam, 1973–1975",date:"2012",publicationOrArchive:"Encounter Books",supportsClaim:"Tells how South Vietnam fell in 55 days: aid cuts, shortages of fuel and ammunition, and the retreat from the Central Highlands.",limitations:"Veith is sympathetic to South Vietnam’s army. He argues it could have held out with more American aid and air support.",originalUrl:"https://openlibrary.org/works/OL15901784W",verificationCategory:"VERIFIED_PARAPHRASE"},"c10-2":{id:"c10-2",marker:2,citation:"Dung, Van Tien. Our Great Spring Victory: An Account of the Liberation of South Vietnam. Monthly Review Press, 1977.",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"General Van Tien Dung",title:"Our Great Spring Victory: An Account of the Liberation of South Vietnam",date:"1977",publicationOrArchive:"Monthly Review Press (English translation)",supportsClaim:"The memoir of General Van Tien Dung, North Vietnam’s army chief of staff, on how he planned the 1975 offensive and the capture of Saigon.",limitations:"Written by the winning general to celebrate the victory. It plays down South Vietnamese resistance and disagreements among his own commanders.",originalUrl:"https://openlibrary.org/works/OL9281873W",verificationCategory:"VERIFIED_PARAPHRASE"},"c10-3":{id:"c10-3",marker:3,citation:"Snepp, Frank. Decent Interval: An Insider’s Account of Saigon’s Indecent End. Random House, 1977.",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Frank Snepp",title:"Decent Interval: An Insider’s Account of Saigon’s Indecent End",date:"1977",publicationOrArchive:"Random House",supportsClaim:"Frank Snepp, a CIA analyst in Saigon, describes officials who ignored the warning signs, and how many Vietnamese who had worked with the Americans were left behind.",limitations:"A personal memoir by an angry insider. The CIA took him to court for publishing it without its approval.",originalUrl:"https://openlibrary.org/works/OL4149633W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q016",chapter:10,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"In Black April, military historian George J. Veith documents how North Vietnamese armored units rammed through the iron gates of Saigon’s Presidential Palace at 11:30 a.m. on April 30, 1975, capturing President Duong Van Minh and concluding the military collapse of the Republic of Vietnam.",source:"Black April: The Fall of South Vietnam, 1973–1975",authorOrCreator:"George J. Veith",institution:"Encounter Books / Historical Monograph",date:"2012",sourceUrl:"https://www.encounterbooks.com/books/black-april/",locator:"Encounter Books, 2012, Chapter 19, pp. 488–492",locatorStatus:"supported",verified:!0,sourceType:"SCHOLARLY_SECONDARY_SOURCE",supportsClaim:"Describes the last days of the Ho Chi Minh Campaign and South Vietnam’s surrender on April 30, 1975.",limitations:"This is our summary of Veith’s account, not his exact words.",conversionStatus:"converted_to_paraphrase",notes:"Historical narrative verified against Veith (2012). Quotation marks permanently removed."}]],29893);var c=e.i(29893);e.s(["citations",0,{"c11-1":{id:"c11-1",marker:1,citation:"Robinson, W. Courtland. Terms of Refuge: The Indochinese Exodus and the International Response. Zed Books, 1998.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"W. Courtland Robinson",title:"Terms of Refuge: The Indochinese Exodus and the International Response",date:"1998",publicationOrArchive:"Zed Books / UNHCR Study",supportsClaim:"A study of the refugees who fled Vietnam, Laos and Cambodia after 1975, including the boat people.",limitations:"About refugee camps and resettlement in other countries, not life inside Vietnam.",originalUrl:"https://openlibrary.org/works/OL1915581W",verificationCategory:"VERIFIED_PARAPHRASE"},"c11-2":{id:"c11-2",marker:2,citation:'Hirschman, Charles, et al. "Vietnamese Casualties During the American War: A New Estimate." Population and Development Review, 1995.',sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Charles Hirschman, Samuel Preston, and Vu Manh Loi",title:"Vietnamese Casualties During the American War: A New Estimate",date:"1995",publicationOrArchive:"Population and Development Review, Vol. 21, No. 4",locator:"Vol. 21, No. 4, pp. 783–812",supportsClaim:"A study that estimates about one million Vietnamese died in the war from 1965 to 1975, soldiers and civilians together.",limitations:"An estimate built from surveys and population data, not a count of each death.",originalUrl:"https://www.jstor.org/stable/2137774",verificationCategory:"VERIFIED_PARAPHRASE"},"c11-3":{id:"c11-3",marker:3,citation:"Evans, Grant, and Kelvin Rowley. Red Brotherhood at War: Vietnam, Cambodia and Laos since 1975. Verso, 1990.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Grant Evans and Kelvin Rowley",title:"Red Brotherhood at War: Vietnam, Cambodia and Laos since 1975",date:"1990",publicationOrArchive:"Verso Books (Revised Edition)",supportsClaim:"Covers the wars between communist countries after 1975: Vietnam’s invasion of Cambodia to remove the Khmer Rouge, and China’s attack on Vietnam.",limitations:"About the conflicts between countries, not life or healing inside Vietnam.",originalUrl:"https://openlibrary.org/works/OL1662186W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[{id:"Q011",chapter:11,type:"claim",verificationCategory:"VERIFIED_PARAPHRASE",text:"On April 4, 1995, an Associated Press wire reported that the Vietnamese government had officially released its comprehensive war casualty figures, disclosing that 1.1 million North Vietnamese and Viet Cong combatants died, 600,000 were wounded, and approximately 2 million civilians died on both sides during the 1954–1975 war.",source:'Associated Press Wire: "Vietnam Releases First Official War Casualty Figures"',authorOrCreator:"Associated Press Wire Service",institution:"The Associated Press (Hanoi Bureau)",date:"April 4, 1995",sourceUrl:"https://apnews.com/",locator:"The Virginian-Pilot / AP Wire Archive, April 4, 1995",locatorStatus:"supported",verified:!0,sourceType:"CONTEMPORARY_REPORTING",supportsClaim:"A 1995 news report on the war death figures Vietnam’s government released twenty years after the war ended.",limitations:"These are the government’s own numbers, released long after the war. We describe the report in our own words.",conversionStatus:"converted_to_paraphrase",notes:"Casualty figures verified against AP dispatch of April 4, 1995. Quotation marks removed."}]],66729);var d=e.i(66729);e.s(["citations",0,{"c12-1":{id:"c12-1",marker:1,citation:"Halberstam, David. The Best and the Brightest. Random House, 1972.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"David Halberstam",title:"The Best and the Brightest",date:"1972",publicationOrArchive:"Random House",supportsClaim:"The founding book of the orthodox view. It argues that confident, clever officials under Kennedy and Johnson led the country into the war.",limitations:"A reporter wrote it in 1972, before the White House tapes and foreign records were opened.",originalUrl:"https://openlibrary.org/works/OL109599W",verificationCategory:"VERIFIED_PARAPHRASE"},"c12-2":{id:"c12-2",marker:2,citation:"Summers, Harry G. On Strategy: A Critical Analysis of the Vietnam War. Presidio Press, 1982.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Colonel Harry G. Summers Jr.",title:"On Strategy: A Critical Analysis of the Vietnam War",date:"1982",publicationOrArchive:"Presidio Press / U.S. Army War College",supportsClaim:"A revisionist argument by an Army colonel: the United States should have fought North Vietnam as a regular war instead of chasing guerrillas in the South.",limitations:"Later historians say he underrated how strong the southern rebellion was, and the risk of a war with China.",originalUrl:"https://openlibrary.org/works/OL2931119W",verificationCategory:"VERIFIED_PARAPHRASE"},"c12-3":{id:"c12-3",marker:3,citation:"Logevall, Fredrik. Choosing War: The Lost Chance for Peace and the Escalation of War in Vietnam. University of California Press, 1999.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Fredrik Logevall",title:"Choosing War: The Lost Chance for Peace and the Escalation of War in Vietnam",date:"1999",publicationOrArchive:"University of California Press",supportsClaim:"Argues that the war was not inevitable. Between 1963 and 1965, leaders chose war partly because they feared looking weak at home.",limitations:"About choices made by presidents and diplomats, not the momentum of the fighting.",originalUrl:"https://openlibrary.org/works/OL6211304W",verificationCategory:"VERIFIED_PARAPHRASE"},"c12-4":{id:"c12-4",marker:4,citation:"Nguyen, Lien-Hang T. Hanoi’s War: An International History of the War for Peace in Vietnam. University of North Carolina Press, 2012.",sourceType:"SCHOLARLY_SECONDARY_SOURCE",authorOrInstitution:"Lien-Hang T. Nguyen",title:"Hanoi’s War: An International History of the War for Peace in Vietnam",date:"2012",publicationOrArchive:"University of North Carolina Press",supportsClaim:"Uses Vietnamese records to show that Hanoi’s leaders were not just following Moscow or Beijing. They made their own war plans and played the big powers against each other.",limitations:"About North Vietnam’s leaders and diplomacy, not American public opinion.",originalUrl:"https://openlibrary.org/works/OL16416536W",verificationCategory:"VERIFIED_PARAPHRASE"}},"sources",0,[]],41996);let u=[t,i,o,a,r,n,s,h,l,c,d,e.i(41996)],m=u.flatMap(e=>e.sources),p=function(e){let t={};for(let i of e)for(let[e,o]of Object.entries(i)){if(e in t)throw Error(`Duplicate citation id "${e}" in CITATION_REGISTRY`);t[e]=o}return t}([...u.map(e=>e.citations),{Q001:{id:"Q001",marker:1,citation:"Telegram from Ho Chi Minh to President Harry S. Truman (Feb 28, 1946). NARA RG 226, Entry 140, Box 39 / DocsTeach ID 595462.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Ho Chi Minh",title:"Telegram from Ho Chi Minh to President Harry S. Truman",date:"February 28, 1946",publicationOrArchive:"U.S. National Archives (NARA), Record Group 226 / DocsTeach ID 595462",locator:"NARA RG 226, Entry 140, Box 39 / DocsTeach ID 595462",supportsClaim:"Shows Ho Chi Minh writing to President Truman to ask for U.S. help against France. He pointed to the Atlantic Charter and the United Nations Charter.",limitations:"Truman never answered. Rebuilding ties with France in Europe mattered more to his government.",originalUrl:"https://docsteach.org/document/ho-chi-minh-to-truman/",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"I therefore earnestly appeal to you personally and to the American people to interfere urgently in support of our independence and help making the negotiations more in keeping with the principles of the Atlantic and San Francisco charters."},Q002:{id:"Q002",marker:2,citation:"National Security Council Policy Statement on Indochina (NSC 64). FRUS 1950, Vol. VI, Document 480, pp. 745–747.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"National Security Council",title:"The Position of the United States with Respect to Indochina (NSC 64)",date:"February 27, 1950",publicationOrArchive:"Foreign Relations of the United States (FRUS) 1950, Vol. VI",locator:"FRUS 1950, Vol. VI, Document 480, pp. 745–747, Conclusions Para 10",supportsClaim:"The 1950 policy paper, NSC 64, that explained why the United States would help pay for France’s war in Indochina: to stop communism from spreading in the region.",limitations:"It covers Southeast Asia only. Don’t mix it up with NSC 68, the broader Cold War plan written two months later.",originalUrl:"https://history.state.gov/historicaldocuments/frus1950v06/d480",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"It is important to United States security interests that all practicable measures be taken to prevent further communist expansion in Southeast Asia. Indochina is a key area of Southeast Asia and is under immediate threat."},Q010:{id:"Q010",marker:1,citation:"Agreement on Ending the War and Restoring Peace in Viet-Nam (The Paris Peace Accords), January 27, 1973. United Nations Treaty Series, Vol. 935, No. 13295, Chapter I, Article 1, p. 4.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"William P. Rogers, Nguyen Duy Trinh, Tran Van Lam, Nguyen Thi Binh",title:"Agreement on Ending the War and Restoring Peace in Viet-Nam",date:"January 27, 1973",publicationOrArchive:"United Nations Treaty Series, Vol. 935",locator:"United Nations Treaty Series (UNTS), Vol. 935, No. 13295, Chapter I, Article 1, p. 4",supportsClaim:"Article 1 of the 1973 Paris Peace Accords, in which the United States promised to respect Vietnam’s independence and unity as recognized at Geneva in 1954.",limitations:"Only Article 1 is quoted exactly. The chapter describes the other articles in its own words.",originalUrl:"https://treaties.un.org/doc/Publication/UNTS/Volume%20935/v935.pdf",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"The United States and all other countries respect the independence, sovereignty, unity, and territorial integrity of Viet-Nam as recognized by the 1954 Geneva Agreements on Viet-Nam."},Q004:{id:"Q004",marker:1,citation:"State Department Cable 243 to Embassy Saigon (The Coup Cable). FRUS 1961–1963, Vol. IV, Document 268.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Roger Hilsman, Averell Harriman, George Ball",title:"State Department Telegram 243 to Embassy Saigon",date:"August 24, 1963",publicationOrArchive:"Foreign Relations of the United States (FRUS) 1961–1963, Vol. IV",locator:"FRUS 1961–1963, Vol. IV, Document 268 (Telegram 243)",supportsClaim:"The August 1963 cable telling Ambassador Henry Cabot Lodge Jr. that Diem must get rid of his brother Nhu, and that the United States would accept a coup if he refused.",limitations:"It did not order anyone to kill Diem. Kennedy was shaken when he learned the generals had killed Diem and Nhu.",originalUrl:"https://history.state.gov/historicaldocuments/frus1961-63v04/d268",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"US Government cannot tolerate situation in which power lies in Nhu's hands. Diem must be given chance to rid himself of Nhu and his coterie and replace them with best military and political personalities available. If, in spite of all of your efforts, Diem remains obdurate and refuses, then we must face the possibility that Diem himself cannot be preserved."},Q005:{id:"Q005",marker:2,citation:'Hanyok, Robert J. "Skunks, Bogies, Silent Hounds, and the Flying Fish." Cryptologic Quarterly, NSA, 2001.',sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Robert J. Hanyok (NSA Center for Cryptologic History)",title:"Skunks, Bogies, Silent Hounds, and the Flying Fish: The Gulf of Tonkin Mystery, 2–4 August 1964",date:"Winter 2000 / Spring 2001 (Declassified 2005)",publicationOrArchive:"Cryptologic Quarterly, Vol. 19/20 / NSA-EBB-132",locator:"Cryptologic Quarterly, Vol. 19/20, p. 1",supportsClaim:"The National Security Agency’s own history of the Gulf of Tonkin. It found that the intercepted messages used as proof of an August 4 attack were really about the August 2 fight.",limitations:"It blames analysts who passed along only the evidence that fit, not top officials knowingly making up an attack.",originalUrl:"https://nsarchive2.gwu.edu/NSAEBB/NSAEBB132/",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"First, it is not simply that there is a different story as to what happened; it is that no attack happened that night."},Q006:{id:"Q006",marker:3,citation:"Joint Resolution of Congress, Public Law 88-408 (The Gulf of Tonkin Resolution). 78 Stat. 384, Sec. 1.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"88th United States Congress",title:"The Gulf of Tonkin Resolution (Public Law 88-408)",date:"August 7, 1964",publicationOrArchive:"United States Statutes at Large, 78 Stat. 384",locator:"78 Stat. 384, Section 1",supportsClaim:"The 1964 Gulf of Tonkin Resolution, which let President Johnson use military force in Southeast Asia without a declaration of war.",limitations:"It passed 416 to 0 in the House and 88 to 2 in the Senate. Congress voted after being told the ships had been attacked without reason.",originalUrl:"https://www.archives.gov/milestone-documents/tonkin-gulf-resolution",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"Resolved by the Senate and House of Representatives of the United States of America in Congress assembled, That the Congress approves and supports the determination of the President, as Commander in Chief, to take all necessary measures to repel any armed attack against the forces of the United States and to prevent further aggression."},Q013:{id:"Q013",marker:4,citation:"Telegram 041727Z AUG 64 from CTG 72.1 to CINCPACFLT. FRUS 1964–1968, Vol. I, Document 117.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Captain John J. Herrick (Commander, Task Group 72.1)",title:"Flash Telegram 041727Z AUG 64 from CTG 72.1 to CINCPACFLT",date:"August 4, 1964 (1:27 PM EDT)",publicationOrArchive:"Foreign Relations of the United States (FRUS) 1964–1968, Vol. I",locator:"FRUS 1964–1968, Vol. I, Document 117 (Telegram 041727Z)",supportsClaim:"The cable in which the commander at sea, Captain John Herrick, warned Washington that the August 4 attack looked doubtful. It arrived hours before Johnson went on television.",limitations:"Herrick was not sure no attack had happened. He reported confusing radar and sonar readings and asked for a full review.",originalUrl:"https://history.state.gov/historicaldocuments/frus1964-68v01/d117",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"Review of action makes many reported contacts and torpedoes fired appear doubtful. Freak weather effects on radar and overeager sonarmen may have accounted for many reports. No actual visual sightings by Maddox. Suggest complete evaluation before any further action taken."},Q021:{id:"Q021",marker:5,citation:"Stockdale, James B., and Sybil Stockdale. In Love and War: The Story of a Family’s Ordeal and Sacrifice During the Vietnam Years. Harper & Row, 1984, p. 118.",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Commander James B. Stockdale",title:"In Love and War: The Story of a Family’s Ordeal and Sacrifice During the Vietnam Years",date:"1984",publicationOrArchive:"Harper & Row",locator:"Harper & Row, 1984, Chapter 6, p. 118",supportsClaim:"James Stockdale, a Navy pilot flying overhead on August 4, says he saw the destroyers firing but no enemy boats.",limitations:"He wrote this in a memoir twenty years later, and he could see only so much at night in bad weather. It matches the doubts Herrick reported that night.",originalUrl:"https://www.worldcat.org/title/in-love-and-war/oclc/10751939",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"I had the best seat in the house to watch that event, and our destroyers were just shooting at phantom targets—there were no PT boats there... There was nothing there but black water and American firepower."},Q014:{id:"Q014",marker:1,citation:'CBS News Special Report: "Who, What, When, Where, Why: Report from Vietnam by Walter Cronkite." Feb 27, 1968.',sourceType:"CONTEMPORARY_REPORTING",authorOrInstitution:"Walter Cronkite",title:'CBS News Special Report: "Report from Vietnam"',date:"February 27, 1968",publicationOrArchive:"CBS News Television Broadcast",locator:"Broadcast transcript as reprinted in Reporting Vietnam, Part One: American Journalism 1959–1969 (Library of America, 1998), pp. 581–582",supportsClaim:"Walter Cronkite’s closing words on CBS in February 1968, after he went to Vietnam to see the war for himself following Tet.",limitations:"A famous line, What the hell is going on?, is often credited to him on air. He never said it in the broadcast.",originalUrl:"https://www.digitalhistory.uh.edu/active_learning/explorations/vietnam/cronkite.cfm",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"To say that we are closer to victory today is to believe, in the face of the evidence, the optimists who have been wrong in the past. To suggest we are on the edge of defeat is to yield to unreasonable pessimism. To say that we are mired in stalemate seems the only realistic, yet unsatisfactory, conclusion."},Q022:{id:"Q022",marker:5,citation:"Congressional Record — Senate Floor Debate on Tonkin Resolution. Vol. 110, Part 14, pp. 18470–18471.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Senator Wayne Morse (D-OR)",title:"Speech on the Senate Floor Debating the Gulf of Tonkin Resolution",date:"August 7, 1964",publicationOrArchive:"Congressional Record, 88th Cong., 2nd Sess., Vol. 110, Part 14",locator:"Congressional Record, Vol. 110, Part 14, pp. 18470–18471",supportsClaim:"Senate debate in which Wayne Morse warned that the resolution handed Congress’s power to make war to the president, based on claims nobody had checked.",limitations:"Morse and Ernest Gruening were the only two senators to vote no. 88 voted yes.",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"I believe that history will record that we have made a great mistake in subverting and circumventing the Constitution of the United States. . . I believe this resolution to be a historic mistake."},Q023:{id:"Q023",marker:6,citation:"The Fog of War: Eleven Lessons from the Life of Robert S. McNamara (Directed by Errol Morris, 2003).",sourceType:"LATER_HISTORICAL_ANALYSIS",authorOrInstitution:"Robert S. McNamara",title:"The Fog of War: Eleven Lessons from the Life of Robert S. McNamara",date:"2003",publicationOrArchive:"Sony Pictures Classics / Documentary Record",locator:'Lesson #4 ("Belief and Seeing")',supportsClaim:"Robert McNamara, Johnson’s secretary of defense, admitting years later that the August 4 attack did not happen.",limitations:"An interview filmed about forty years later. It shows what he thought looking back, not what he thought in 1964.",originalUrl:"https://www.sonyclassics.com/fogofwar/",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"It was just confusion, and events afterward showed that our judgment that we’d been attacked that day was wrong. It didn’t happen."},Q024:{id:"Q024",marker:7,citation:"USS Maddox (DD-731) Operational Flash Message (August 2, 1964). NHHC Archives, DTG 020640Z AUG 64.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Commander Task Group 72.1 / USS Maddox",title:"Operational Flash Message DTG 020640Z AUG 64",date:"August 2, 1964",publicationOrArchive:"Naval History and Heritage Command / NARA",locator:"Tonkin Gulf Records, Message DTG 020640Z AUG 64",supportsClaim:"The message the USS Maddox sent on August 2, 1964, reporting North Vietnamese torpedo boats closing in.",limitations:"It is about the real daylight fight on August 2, not the disputed night of August 4.",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"AM BEING APPROACHED BY HIGH SPEED CRAFT WITH APPARENT INTENTION OF TORPEDO ATTACK. INTEND TO OPEN FIRE IF NECESSARY SELF DEFENSE."},Q025:{id:"Q025",marker:2,citation:"Arnett, Peter. Associated Press Wire Dispatch from Ben Tre, South Vietnam. Published Feb 7–8, 1968.",sourceType:"CONTEMPORARY_REPORTING",authorOrInstitution:"Peter Arnett quoting an unnamed U.S. Army Major",title:"Associated Press Wire Dispatch from Ben Tre, South Vietnam",date:"February 7, 1968",publicationOrArchive:"The New York Times, Feb 8, 1968, p. 14 / AP Archives",locator:"The New York Times, Feb 8, 1968, p. 14",supportsClaim:"Peter Arnett’s 1968 news report from Ben Tre, quoting an American officer on why so much of the town was destroyed to retake it.",limitations:"The officer was never named. People still argue about who he was and whether his words described the whole war or just that day.",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"‘It became necessary to destroy the town to save it,’ a United States major said today."},Q026:{id:"Q026",marker:2,citation:"Final Declaration of the Geneva Conference on Indo-China. FRUS 1952–1954, Vol. XIII, Part 2, Doc 1035.",sourceType:"PRIMARY_SOURCE",authorOrInstitution:"Participants in the Geneva Conference",title:"Final Declaration of the Geneva Conference on the Problem of Restoring Peace in Indo-China",date:"July 21, 1954",publicationOrArchive:"FRUS 1952–1954, Vol. XIII, Part 2, Document 1035 / Yale Avalon Project",locator:"Paragraph 6 (IC/43 Rev. 2)",supportsClaim:"The 1954 Geneva agreement that split Vietnam at the 17th parallel. It called the line a temporary military boundary, not a border between two countries.",limitations:"The United States and the government in Saigon would not sign it. That let them argue later that it did not bind them.",originalUrl:"https://avalon.law.yale.edu/20th_century/inch005.asp",verificationCategory:"VERIFIED_QUOTATION",exactQuotation:"The Conference recognizes that the essential purpose of the agreement relating to Viet-Nam is to settle military questions with a view to ending hostilities and that the military demarcation line is provisional and should not in any way be interpreted as constituting a political or territorial boundary."}}]);e.s(["_",0,p,"f",0,m],31454)}]);